generalfeedback.text:
[[jsxgraph]]
var board = JXG.JSXGraph.initBoard('jxgbox', {
    boundingbox: [-2, -8, 7, 4],
    axis: false,
    visible:false,
    showCopyright: false,
    showNavigation: false,
    keepAspectRatio: true
});

// Define triangle vertices
var A = board.create('point', [0, 0], {name:'A', size:1});
var B = board.create('point', [6, 0], {name:'B', size:1});
var C = board.create('point', [0, -6], {name:'C', size:1});

// Draw triangle sides
var lineAB = board.create('line', [A, B], {straightFirst:false, straightLast:false, strokeWidth:1});
var lineAC = board.create('line', [A, C], {straightFirst:false, straightLast:false, strokeWidth:1});
var lineBC = board.create('line', [B, C], {straightFirst:false, straightLast:false, strokeWidth:1});

// Mark right angle at vertex A
board.create('angle', [C, A, B], {
    radius:0.7, 
    name:' ', 
    type:'sector', 
    fillColor:'lightgray', 
    fillOpacity:0.5
});


// Mark right angle at vertex C
board.create('angle', [B,C,A], {
    radius:0.7, 
    name:' ', 
    type:'sector', 
    fillColor:'red', 
    fillOpacity:0.5
});


// Mark right angle at vertex B
board.create('angle', [A,B,C], {
    radius:0.7, 
    name:' ', 
    type:'sector', 
    fillColor:'green', 
    fillOpacity:0.5
});


// Label angles of the triangle
board.create('text', [0, -5, '{#angle_BCA#}'+'°']);
board.create('text', [5, -0.2, '{#angle_CBA#}'+'°']);

// Line passing through A using three points
var X = board.create('point', [-4, -2], {name:'X', visible:true, size:1}); 
var Y = board.create('point', [4, 2], {name:'Y', visible:true, size:1});  

var lineXY = board.create('line', [X, Y], {
    strokeColor:'red',
    strokeWidth:1
});

// Label angles along XY line
board.create('text', [-1, -1, '{#angle_CAX#}'+'°']);
board.create('text', [1, 0.3, '{#angle_YAB#}'+'°']);
[[/jsxgraph]]

questionvariables.text:
/* Load proof library */
stack_include_contrib("prooflib.mac");

/****************************************************************/
/* Random angle generation */
angle_BCA : 10 + rand_with_step(30,50,5);
angle_CBA : 90 - angle_BCA;

angle_YAB : 10 + rand_with_step(10,40,1);
angle_CAX : 90 - angle_YAB;

/****************************************************************/
/* Theorem statement */
thm: "Show that \\(XAY\\) is a straight line.";

/****************************************************************/
/* Proof steps */ 
proof_steps: [ ["assumption", "In triangle \\(ABC\\), we know \\(\\angle CBA + \\angle BCA = 90^\\circ\\)."], 

["step1", "At point A, the right angle is adjacent to \\(\\angle CAX\\) and \\(\\angle YAB\\)."], 

["step2", "By construction, \\(\\angle CAX + \\angle YAB = 90^\\circ\\)."], 

["step3", "Therefore, around point A: \\(\\angle BAC + \\angle CAX + \\angle YAB = 180^\\circ\\)."], 

["conclusion", "Since \\(\\angle XAY = 180^\\circ\\), it follows that \\(XAY\\) lies on a straight line (sum of angles on a straight line add up to \\(180^\\circ\\))."] ];

/****************************************************************/
/* Correct proof order */
proof_ans: proof(proof_iff("assumption","step1","step2"),"step3","conclusion");

/* Randomize steps for Parsons-style task */
proof_steps: random_permutation(proof_steps);

/* Generate alternatives for STACK marking */
tal: proof_alternatives(proof_ans);
len1: length(tal);

/* Flatten proofs for feedback display */
tas: setify(map(proof_flatten, tal));
